/**
 * Guard: nothing under src/ may load anything from /reference at runtime.
 *
 * The design sheets are art direction, not assets. If one ever gets imported it
 * would be bundled and shipped, which breaks the project's core rule that every
 * pixel is generated by our own code.
 *
 * The first version of this guard matched any quoted-looking text containing
 * "reference/", which also fired on **doc comments** — including
 * `head.ts`'s note that its skull proportions were read against
 * `/reference/kai/01-neutral-front.jpg`. That citation is provenance worth
 * keeping: it tells the next author which sheet a number came from. A guard that
 * punishes documenting your sources trains people to stop documenting them.
 *
 * So this now looks for the ways a file can actually *load* something —
 * import/export-from, require, dynamic import, `new URL(...)`, fetch, and
 * Three's loaders — and ignores comments entirely.
 */
import { readdir, readFile } from 'node:fs/promises';
import path from 'node:path';

/** Strip line and block comments so prose can mention the directory freely. */
function stripComments(src) {
  return src
    .replace(/\/\*[\s\S]*?\*\//g, '')
    .replace(/(^|[^:])\/\/.*$/gm, '$1');
}

const LOADERS = [
  // import x from '...'  /  export * from '...'  /  import('...')
  /\b(?:import|export)\s[^;]*?['"`]([^'"`]*reference\/[^'"`]*)['"`]/,
  /\bimport\s*\(\s*['"`]([^'"`]*reference\/[^'"`]*)['"`]/,
  /\brequire\s*\(\s*['"`]([^'"`]*reference\/[^'"`]*)['"`]/,
  // new URL('../reference/x.jpg', import.meta.url) — the Vite asset idiom
  /new\s+URL\s*\(\s*['"`]([^'"`]*reference\/[^'"`]*)['"`]/,
  /\b(?:fetch|load|loadAsync|setPath|setResourcePath)\s*\(\s*['"`]([^'"`]*reference\/[^'"`]*)['"`]/,
];

const offenders = [];

async function walk(dir) {
  for (const e of await readdir(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) {
      await walk(p);
    } else if (/\.(ts|tsx|js|mjs|glsl|frag|vert)$/.test(e.name)) {
      const src = stripComments(await readFile(p, 'utf8'));
      for (const re of LOADERS) {
        const m = src.match(re);
        if (m) {
          offenders.push(`${p}  ->  ${m[1]}`);
          break;
        }
      }
    }
  }
}

await walk('src');

if (offenders.length) {
  console.error('Reference images must never be loaded by src/ at runtime:');
  for (const o of offenders) console.error('  ' + o);
  process.exit(1);
}
console.log(`ok: no reference loads in src/ (comments citing sheets are fine)`);
